/// <summary>
/// WolfA 16.03.23
/// Main class for item validation 
/// </summary>
class NDX_ItemValidity
{
    InventTable             inventTable;

    NDXItemValidityDateEconomicBatchSize lNDXItemValidityDateEconomicBatchSize;
    NDXMultipleS_KBV_BuildingProject lNDXMultipleS_KBV_BuildingProject;
    NDXMultipleS_SalesQuotation lNDXMultipleS_SalesQuotation;
    NDXMultipleS_SalesQuotationRange lNDXMultipleS_SalesQuotationRange;
    NDXMultipleS_Sales lNDXMultipleS_Sales;
    NDXMultipleS_CustTable lNDXMultipleS_CustTable;
    NDXMultipleS_smmBusRelChainGroup lNDXMultipleS_smmBusRelChainGroup;

    NDXValidityCheckType    checkType;
    boolean                 lItemValidityTableExists;
    boolean                 lDoAllChecks;
    NDXItemValidityErrors   itemValidityErrors;

    container               result;
    container               conErrorMessage;
    int                     nAnzError;

    date                    checked_Date;
    CustAccount             checked_Debitor;
    smmChainId              checked_Chain;

    NDX_ItemValidityObject  itemValidityObject;

}

Method.Source:
public InventTable parmInventTable(InventTable _inventTable = inventTable)
{
    inventTable = _inventTable;
    return inventTable;
}

public container parmResult(container _result = result)
{
    result = _result;
    return result;
}

public container parmConErrorMessage(container _conErrorMessage = conErrorMessage)
{
    conErrorMessage = _conErrorMessage;
    return conErrorMessage;
}

public Boolean parmLDoAllChecks(Boolean _lDoAllChecks = lDoAllChecks)
{
    ;
    lDoAllChecks = _lDoAllChecks;

    if (lDoAllChecks)
    {
        itemValidityErrors  = null;
        nAnzError           = 0;
    }

    return lDoAllChecks;
}

public Boolean parmLItemValidityTableExists(Boolean _lItemValidityTableExists = lItemValidityTableExists)
{
    lItemValidityTableExists = _lItemValidityTableExists;
    return lItemValidityTableExists;
}

public Date parmChecked_Date(Date _checked_Date = checked_Date)
{
    checked_Date = _checked_Date;
    return checked_Date;
}

public Custaccount parmChecked_Debitor(Custaccount _checked_Debitor = checked_Debitor)
{
    checked_Debitor = _checked_Debitor;
    return checked_Debitor;
}

public SmmChainId parmChecked_Chain(SmmChainId _checked_Chain = checked_Chain)
{
    checked_Chain = _checked_Chain;
    return checked_Chain;
}

public NDXValidityCheckType parmCheckType(NDXValidityCheckType _checkType = checkType)
{
    checkType = _checkType;
    return checkType;
}

public NDX_ItemValidityObject parmItemValidityObject(NDX_ItemValidityObject _itemValidityObject = itemValidityObject)
{
    itemValidityObject = _itemValidityObject;
    return itemValidityObject;
}

public NDXEconomicBatchSize parmEconomicBatchSize()
{
    return lNDXItemValidityDateEconomicBatchSize.EconomicBatchSize;
}

protected void new(InventTable  _inventTable, NDXValidityCheckType _checkType)
{
    ;
    lDoAllChecks                = false;
    nAnzError                   = 0;
    inventTable                 = _inventTable;
    checkType                   = _checkType;

    this.initValidityTables(_inventTable);
}

static public NDX_ItemValidity construct(NDX_ItemValidityObject _ndx_ItemValidityObject, NDXValidityCheckType _checkType = NDXValidityCheckType::QuotationNumber, boolean _doAllChecks = false)
{
    InventTable inventTable = InventTable::find(_ndx_ItemValidityObject.parmCheck_ItemId());
    NDX_ItemValidity ndx_ItemValidity = new NDX_ItemValidity(inventTable, _checkType);

    ndx_ItemValidity.parmItemValidityObject(_ndx_ItemValidityObject);
    ndx_ItemValidity.parmCheckType(_checkType);
    ndx_ItemValidity.parmLDoAllChecks(_doAllChecks);

    return ndx_ItemValidity;
}

private void initValidityTables(InventTable  _inventTable)
{
    lNDXItemValidityDateEconomicBatchSize = NDXItemValidityDateEconomicBatchSize::find(_inventTable);
    lNDXMultipleS_KBV_BuildingProject = NDXMultipleS_KBV_BuildingProject::find(_inventTable);
    lNDXMultipleS_SalesQuotation = NDXMultipleS_SalesQuotation::find(_inventTable);
    lNDXMultipleS_SalesQuotationRange = NDXMultipleS_SalesQuotationRange::find(_inventTable);
    lNDXMultipleS_Sales = NDXMultipleS_Sales::find(_inventTable);
    lNDXMultipleS_CustTable = NDXMultipleS_CustTable::find(_inventTable);
    lNDXMultipleS_smmBusRelChainGroup = NDXMultipleS_smmBusRelChainGroup::find(_inventTable);

    lItemValidityTableExists = lNDXItemValidityDateEconomicBatchSize ||
                                lNDXMultipleS_KBV_BuildingProject ||
                                lNDXMultipleS_SalesQuotation ||
                                lNDXMultipleS_Sales ||
                                lNDXMultipleS_CustTable ||
                                lNDXMultipleS_smmBusRelChainGroup;
}

/// <summary>
/// Checks if Item is valid for quotation check
/// </summary>
/// <returns>true or false</returns>
boolean hasValidityChecksQuotation()
{
    return (NDXMultipleS_KBV_BuildingProject::hasValidityCheck(inventTable) == NoYes::Yes
        || NDXMultipleS_smmBusRelChainGroup::hasValidityCheck(inventTable) == NoYes::Yes
        || NDXMultipleS_CustTable::hasValidityCheck(inventTable) == NoYes::Yes
        || NDXItemValidityDateEconomicBatchSize::hasValidityCheck(inventTable) == NoYes::Yes
        || NDXMultipleS_SalesQuotation::hasValidityCheck(inventTable) == NoYes::Yes);
}

/// <summary>
/// Checks if item is valid for sales check
/// </summary>
/// <returns>true or false</returns>
boolean hasValidityChecksSale()
{
    return (NDXMultipleS_Sales::hasValidityCheck(inventTable) == NoYes::Yes
        || NDXMultipleS_smmBusRelChainGroup::hasValidityCheck(inventTable) == NoYes::Yes
        || NDXMultipleS_CustTable::hasValidityCheck(inventTable) == NoYes::Yes
        || NDXItemValidityDateEconomicBatchSize::hasValidityCheck(inventTable) == NoYes::Yes);

}

/// <summary>
/// Adds Validity error message record to table
/// </summary>
/// <param name = "nDX_ItemValidityErrors">Error message record</param>
void addErrorMessage(NDXItemValidityErrors nDX_ItemValidityErrors)
{
    ;
    itemValidityErrors.clear();
    buf2Buf(nDX_ItemValidityErrors, itemValidityErrors);
    itemValidityErrors.insert();

    ++nAnzError;
}

/// <summary>
/// Collects all error messages into a container
/// </summary>
/// <returns>container filled with error messages</returns>
container getConErrorMessageAll()
{
    container   conRet = connull();
    int         nAnz;
    ;
    if (nAnzError)
    {
        // Die %1positionserfassung des Artikels [%2] ist nicht zulässig!
        conRet += strfmt("@NDX:NDXItemValidityPositioningMessage", checkType == NDXValidityCheckType::SalesNumber ? "@SYS19627" : "@SYS110882", inventTable.ItemId);
        // Die Gültigkeitsvalidierung war aus folgenden [%1] Gründen nicht erfolgreich:
        conRet += strfmt("@NDX:NDXItemValidityNotSuccessfulReasons", nAnzError);

        while select itemValidityErrors
        {
            ++nAnz;
            conRet += strfmt('%1.) %2', nAnz, itemValidityErrors.checkMessage);        // %1.) %2
            conRet += itemValidityErrors.ErrorMessage;
        }
    }

    return conRet;
}

/// <summary>
/// Checks if item meets the date criteria
/// </summary>
/// <param name = "_date">date</param>
/// <returns>result container</returns>
public container isValidDate(date _date = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
{
    NDXItemValidityErrors      nDX_ItemValidityErrors;
    NDXValidityMessage validityMessage = '';
    boolean     lIsValid = true;

    // keine Gültigkeitseinschränkung
    if (!lItemValidityTableExists)
    {
        return [true, nDX_ItemValidityErrors];
    }

    if (!lNDXItemValidityDateEconomicBatchSize)
    {
        return [true, nDX_ItemValidityErrors];
    }

    // Von-Zeitraum nicht erfüllt
    if (lNDXItemValidityDateEconomicBatchSize.DateFrom && lNDXItemValidityDateEconomicBatchSize.DateFrom > _date)
    {
        nDX_ItemValidityErrors.ValidityCheckType = NDXValidityCheckType::DateFrom;
        nDX_ItemValidityErrors.checkMessage      = strfmt("@NDX:NDXItemValidityTestDateFrom", _date); // Prüfung: Von-Datum [%1]

        //Der Artikel [%1] darf erst ab dem [%2] verwendet werden!
        validityMessage = strfmt("@NDX:NDXItemValidityTestDateMessage", inventTable.ItemId, lNDXItemValidityDateEconomicBatchSize.DateFrom);
        nDX_ItemValidityErrors.ErrorMessage = validityMessage;

        this.addErrorMessage(nDX_ItemValidityErrors);

        if (!lDoAllChecks)
        {
            return [false, nDX_ItemValidityErrors];
        }
    }

    // Bis-Zeitraum nicht erfüllt
    if (lNDXItemValidityDateEconomicBatchSize.DateTo && lNDXItemValidityDateEconomicBatchSize.DateTo < _date)
    {
        nDX_ItemValidityErrors.ValidityCheckType = NDXValidityCheckType::DateTo;
        nDX_ItemValidityErrors.checkMessage      = strfmt("@NDX:NDXItemValidityTestDateTo", _date);

        // Der Artikel [%1] darf nur bis zum [%2] verwendet werden!
        validityMessage = strfmt("@NDX:NDXItemValidityTestDateMessage1", inventTable.ItemId, lNDXItemValidityDateEconomicBatchSize.DateTo);
        nDX_ItemValidityErrors.ErrorMessage = validityMessage;
        this.addErrorMessage(nDX_ItemValidityErrors);
        return [false, nDX_ItemValidityErrors];
    }
    return [lIsValid, nDX_ItemValidityErrors];
}

/// <summary>
/// Constructor for quotation check
/// </summary>
/// <param name = "_inventTable">Item as InventTable recird</param>
/// <param name = "lDoAllChecks">True or false to make all checks</param>
/// <returns>NDX_ItemValidity object</returns>
static NDX_ItemValidity nDX_ItemValidity_Quotation(InventTable  _inventTable, boolean lDoAllChecks = false)
{
    NDX_ItemValidity        nDX_ItemValidity;

    nDX_ItemValidity = new NDX_ItemValidity(_inventTable, NDXValidityCheckType::QuotationNumber);
    nDX_ItemValidity.parmLDoAllChecks(lDoAllChecks);

    return nDX_ItemValidity;
}

