{
    NDX_ItemValidity        nDX_ItemValidity;

    nDX_ItemValidity = new NDX_ItemValidity(_inventTable, NDXValidityCheckType::SalesNumber);
    nDX_ItemValidity.parmLDoAllChecks(lDoAllChecks);

