/// <summary>
/// Checks if item meets the quotation criteria
/// </summary>
/// <param name = "_itemId">_itemId</param>
/// <param name = "_quotationId">_quotationId</param>
/// <param name = "_bvId">building project id</param>
/// <param name = "_accountNum">customer account number</param>
/// <param name = "_checkDate">date</param>
/// <param name = "_lDoAllChecks">do all checks true or false</param>
/// <param name = "_oItemValidity">itemValidity object</param>
/// <returns>container with the check result</returns>
static public container checkValidityQuotation(ItemId _itemId,
                                    QuotationIdBase           _quotationId,
                                    KCS_KBVBuildingProjectID  _bvId = '',
                                    CustAccount               _accountNum = '',
                                    date                      _checkDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
                                    boolean                   _lDoAllChecks = false,
                                    NDX_ItemValidity          _oItemValidity =  null)
{
    inventTable                             inventTable = InventTable::find(_itemId);

    KCS_KBVBuildingProjectTable             kcs_KBVBuildingProjectTable;
    SalesQuotationTable                     salesQuotationTable;
    CustTable                               custTable;
    smmBusRelChainGroup                     smmBusRelChainGroup;

    NDXItemValidityErrors                   nDX_ItemValidityErrors;

    NDX_MultipleS_Quotation_Item            oMultipleS_Quotation_Item;
    NDX_MultipleS_QuotationRange_Item       oMultipleS_QuotationRange_Item;
    NDX_MultipleS_KBV_BuildingProject_Item  oMultipleS_KBV_BuildingProject_Item;
    NDX_MultipleS_Customer_Item             oMultipleS_Customer_Item;
    NDX_MultipleS_Chain_Item                oMultipleS_Chain_Item;

    NDXValidityMessage                      validityMessage, validityMessage2, validityMessage1;
    boolean                                 isValid, isValid2, isValid1 = true;
    container                               conErrorMessage = connull();

    if (!_oItemValidity)
    {
        _oItemValidity =  NDX_ItemValidity::nDX_ItemValidity_Quotation(inventTable, _lDoAllChecks);
    }

    // keine Gültigkeitseinschränkung
    if (!_oItemValidity.parmLItemValidityTableExists() || !_oItemValidity.hasValidityChecksQuotation())
    {
        return [isValid1, conErrorMessage];
    }

    // 1.Gültigkeitsprüfung: Datum
    salesQuotationTable = SalesQuotationTable::find(_quotationId);

    if (_oItemValidity.parmChecked_Date() != _checkDate)
    {
        [isValid, nDX_ItemValidityErrors] = _oItemValidity.isValidDate(_checkDate);

        if (!isValid)
        {
            isValid1         = isValid1 && isValid;
            conErrorMessage += nDX_ItemValidityErrors.checkMessage;
            conErrorMessage += nDX_ItemValidityErrors.ErrorMessage;

            if (!_lDoAllChecks)
            {
                return [isValid1, conErrorMessage];
            }
        }
    }

    // 2.Gültigkeitsprüfung: Angebotsnummer / (Angebots-Bereich)
    oMultipleS_Quotation_Item = NDX_MultipleS_Quotation_Item::new_FromNDX_ItemValidity(_oItemValidity, salesQuotationTable);
    [isValid, validityMessage] = oMultipleS_Quotation_Item.isValid();

    if (!isValid)
    {
        // Zusatzprüfung: Angebotsbereich
        oMultipleS_QuotationRange_Item = NDX_MultipleS_QuotationRange_Item::new_FromNDX_ItemValidity(_oItemValidity, salesQuotationTable.QuotationId);

        if(oMultipleS_QuotationRange_Item.isRangeEmpty())
        {
            isValid1 = isValid && isValid1;
        }
        else
        {
            [isValid2, validityMessage2] = oMultipleS_QuotationRange_Item.isValid();
            isValid1 = isValid1 && isValid2;
        }

        if (!isValid2)
        {
            if (validityMessage)
            {
                conErrorMessage += validityMessage;
            }
            if (validityMessage2)
            {
                conErrorMessage += validityMessage2;
            }
        }

        if (!_lDoAllChecks)
        {
            return [isValid1, conErrorMessage];
        }
    }

    // 3.Gültigkeitsprüfung: Bauvorhaben
    if (!_bvId)
    {
        // BV zum Angebot ermitteln
        _bvId = salesQuotationTable.KCS_KBVBuildingProjectID;
    }

    if (_bvId)
    {
        kcs_KBVBuildingProjectTable = KCS_KBVBuildingProjectTable::find(_bvId);

        oMultipleS_KBV_BuildingProject_Item = NDX_MultipleS_KBV_BuildingProject_Item::new_FromNDX_ItemValidity(_oItemValidity, kcs_KBVBuildingProjectTable);

        [isValid, validityMessage] = oMultipleS_KBV_BuildingProject_Item.isValid();

        if (!isValid)
        {
            isValid1         = isValid1 && isValid;
            conErrorMessage += validityMessage;
            if (!_lDoAllChecks)
            {
                return [isValid1, conErrorMessage];
            }
        }
    }

    // 4.Gültigkeitsprüfung: Debitor
    if (_accountNum)
    {
        custTable = CustTable::find(_accountNum);
    }
    else
    {
        salesQuotationTable = SalesQuotationTable::find(_quotationId);
        custTable = CustTable::find(salesQuotationTable.CustAccount);
    }
    if (_oItemValidity.parmChecked_Debitor() != custTable.AccountNum)
    {
        if (custTable)
        {
            oMultipleS_Customer_Item = NDX_MultipleS_Customer_Item::new_FromNDX_ItemValidity(_oItemValidity, custTable);
            [isValid, validityMessage] = oMultipleS_Customer_Item.isValid();
            if (!isValid)
            {
                isValid1         = isValid1 && isValid;
                conErrorMessage += validityMessage;
                if (!_lDoAllChecks)
                {
                    _oItemValidity.parmResult();
                    return [isValid1, conErrorMessage];

                }
            }
        }
    }

    // 5.Gültigkeitsprüfung: Kette
    if (_oItemValidity.parmChecked_Chain() != custTable.CompanyChainId)
    {
        smmBusRelChainGroup = smmBusRelChainGroup::avaFindChainId(custTable.CompanyChainId);

        oMultipleS_Chain_Item = NDX_MultipleS_Chain_Item::new_FromNDX_ItemValidity(_oItemValidity, smmBusRelChainGroup);
        [isValid, validityMessage] = oMultipleS_Chain_Item.isValid();
        if (!isValid)
        {
            isValid1         = isValid1 && isValid;
            conErrorMessage += validityMessage;
            if (!_lDoAllChecks)
            {
                return [isValid1, conErrorMessage];

            }
        }
    }
    return [isValid1, _lDoAllChecks ? _oItemValidity.getConErrorMessageAll() : conErrorMessage];
}

/// <summary>
/// Checks if item meets the sales criteria
/// </summary>
/// <param name = "_itemId">_itemId</param>
/// <param name = "_salesId">_salesId</param>
/// <param name = "_quotationId">_quotationId</param>
/// <param name = "_accountNum">customer account number</param>
/// <param name = "_checkDate">date</param>
/// <param name = "_lDoAllChecks">do all checks true or false</param>
/// <returns>container with the check result</returns>
static container checkValiditySale(ItemId                _itemId,
                               SalesIdBase               _salesId,
                               QuotationId               _quotationId,
                               CustAccount               _accountNum = '',
                               date                      _checkDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
                               boolean                   _lDoAllChecks = false)
{
    inventTable                             inventTable = InventTable::find(_itemId);
    CustTable                               custTable;
    SalesTable                              salesTable;
    smmBusRelChainGroup                     smmBusRelChainGroup;

    NDXItemValidityErrors                   nDX_ItemValidityErrors;

    NDX_ItemValidity                        oItemValidity;
    NDX_MultipleS_Sales_Item                oMultipleS_Sales_Item;
    NDX_MultipleS_Customer_Item             oMultipleS_Customer_Item;
    NDX_MultipleS_Chain_Item                oMultipleS_Chain_Item;
    NDXValidityMessage                      validityMessage;
    boolean                                 isValid1, isValid = true;
    container                               conErrorMessage = connull();
    ;

    oItemValidity = NDX_ItemValidity::nDX_ItemValidity_Sale(inventTable, _lDoAllChecks);

    // keine Gültigkeitseinschränkung
    if (!oItemValidity.parmLItemValidityTableExists() || !oItemValidity.hasValidityChecksSale())
    {
        return [isValid, conErrorMessage];
    }

    // 1.Gültigkeitsprüfung: Datum
    salesTable = SalesTable::find(_salesId);
    if (prmisdefault(_checkDate) && salesTable)
    {
        _checkDate = DateTimeUtil::date(salesTable.createdDateTime);
    }

    if (oItemValidity.parmChecked_Date() != _checkDate)
    {
        [isValid1, nDX_ItemValidityErrors] = oItemValidity.isValidDate(_checkDate);
        if (!isValid1)
        {
            isValid         = isValid && isValid1;
            conErrorMessage += nDX_ItemValidityErrors.checkMessage;
            conErrorMessage += nDX_ItemValidityErrors.ErrorMessage;
            if (!_lDoAllChecks)
            {
                return [isValid, conErrorMessage];
            }
        }
    }

    // 2.Gültigkeitsprüfung: Auftragsnummer
    oMultipleS_Sales_Item = NDX_MultipleS_Sales_Item::new_FromNDX_ItemValidity(oItemValidity, salesTable);
    [isValid1, validityMessage] = oMultipleS_Sales_Item.isValid();
    if (!isValid1)
    {
        isValid         = isValid && isValid1;
        conErrorMessage += validityMessage;
        if (!_lDoAllChecks)
        {
            return [isValid, conErrorMessage];
        }
    }

    // 3.Gültigkeitsprüfung: Debitor
    if (_accountNum)
    {
        custTable = CustTable::find(_accountNum);
    }
    else
    {
        salesTable = SalesTable::find(_salesId);
        custTable = CustTable::find(salesTable.CustAccount);
    }
    if (oItemValidity.parmChecked_Debitor() != custTable.AccountNum)
    {
        if (custTable)
        {
            oMultipleS_Customer_Item = NDX_MultipleS_Customer_Item::new_FromNDX_ItemValidity(oItemValidity, custTable);
            [isValid1, validityMessage] = oMultipleS_Customer_Item.isValid();
            if (!isValid1)
            {
                isValid         = isValid && isValid1;
                conErrorMessage += validityMessage;
                if (!_lDoAllChecks)
                {
                    return [isValid, conErrorMessage];
                }
            }
        }
    }

    // 4.Gültigkeitsprüfung: Kette
    if (oItemValidity.parmChecked_Chain() != custTable.CompanyChainId)
    {
        smmBusRelChainGroup = smmBusRelChainGroup::avaFindChainId(custTable.CompanyChainId);

        oMultipleS_Chain_Item = NDX_MultipleS_Chain_Item::new_FromNDX_ItemValidity(oItemValidity, smmBusRelChainGroup);
        [isValid1, validityMessage] = oMultipleS_Chain_Item.isValid();
        if (!isValid1)
        {
            isValid         = isValid && isValid1;
            conErrorMessage += validityMessage;
            if (!_lDoAllChecks)
            {
                return [isValid, conErrorMessage];
            }
        }
    }

    // 5. Angebotsprüfung
    if (_quotationId)
    {
        NDX_ItemValidity::checkValidityQuotation(_itemId, _quotationId, '', '', DateTimeUtil::date(salesTable.createdDateTime), _lDoAllChecks, oItemValidity);
    }

    return [isValid, _lDoAllChecks ? oItemValidity.getConErrorMessageAll() : conErrorMessage];
}

/// <summary>
/// Checks if item meets the economic batch size criteria
/// </summary>
/// <param name = "_itemId">_itemId</param>
/// <param name = "_salesQty">quantity</param>
/// <returns>result container</returns>
static container checkValidityEconomicBatchSize(ItemId _itemId, SalesQty _salesQty)
{
    inventTable                             inventTable = InventTable::find(_itemId);

    NDX_ItemValidity                        oItemValidity;
    NDXValidityMessage                      validityMessage;
    boolean                                 isValid = true;
    container                               conErrorMessage = connull();

    oItemValidity =  NDX_ItemValidity::nDX_ItemValidity_Quotation(inventTable);

    // keine Gültigkeitseinschränkung
    if (!oItemValidity.parmLItemValidityTableExists() || !oItemValidity.parmEconomicBatchSize())
    {
        return [isValid, conErrorMessage, 0];
    }

    if (oItemValidity.parmEconomicBatchSize() > _salesQty)
    {
        // Die wirtschaftliche Losgröße von [%1] wurde um [%2] unterschritten!
        validityMessage = strfmt("@NDX:NDXItemValidityEconomicBatchSizeExceeded", oItemValidity.parmEconomicBatchSize(), oItemValidity.parmEconomicBatchSize() - _salesQty, _salesQty);
        isValid = false;
        conErrorMessage += validityMessage;
        return [isValid, conErrorMessage, oItemValidity.parmEconomicBatchSize()];
    }
    return [isValid, conErrorMessage, oItemValidity.parmEconomicBatchSize()];
}

/// <summary>
/// Converts container error messages into a string
/// </summary>
/// <param name = "conErrorMessage">error message container</param>
/// <returns>Validation message</returns>
static NDXValidityMessage conErrorMessage2ValidityMessage(container conErrorMessage)
{
    #define.CR('\n')
    NDXValidityMessage     validityMessage;
    int                     i;
    for (i=1; i <= conlen(conErrorMessage); i++)
    {
        validityMessage += conpeek(conErrorMessage, i) + #CR;
    }

    return validityMessage;
}

static public void main(Args _args)
{
    NDX_ItemValidityObject validityTestObject;
    FormRun caller;
    if(_args == null || _args.object() == null)
    {
        throw error('Test object is null');
    }

    validityTestObject = _args.object() as NDX_ItemValidityObject;
    caller = _args.caller() as INDX_ItemValidityTest;

    validityTestObject.startTest(caller);
}
